import { writeFileSync } from 'node:fs';
const C = (n) => String.fromCharCode(n);
// Python str.isspace() true set (BMP): 09-0D, 1C-1F, 20, 85, A0, 1680, 2000-200A, 2028, 2029, 202F, 205F, 3000
const cands = [0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,0x1680,0x2000,0x2004,0x200a,0x200b,0x2028,0x2029,0x202f,0x205f,0x3000,0xfeff];
const snips = [];
const labels = [];
for (const cp of cands) {
  snips.push(C(cp) + 'hello');           // leading
  labels.push('lead U+' + cp.toString(16));
  snips.push('hello' + C(cp));           // trailing
  labels.push('trail U+' + cp.toString(16));
  snips.push('a\n\n' + C(cp) + '\n\nb'); // whole block
  labels.push('block U+' + cp.toString(16));
  snips.push('a' + C(cp) + '\nb');       // before newline
  labels.push('preNL U+' + cp.toString(16));
}
// STX / ETX
snips.push('a' + C(2) + 'b'); labels.push('STX mid');
snips.push('a' + C(3) + 'b'); labels.push('ETX mid');
snips.push('a' + C(2) + C(3) + 'b'); labels.push('STXETX mid');
writeFileSync('/workspace/probes/parabr-5b.json', JSON.stringify(snips));
writeFileSync('/workspace/probes/parabr-5b.labels.json', JSON.stringify(labels));

