const fs=require("fs");
const out=JSON.parse(fs.readFileSync("/workspace/probes/parabr-5b.out.json","utf8"));
const lab=JSON.parse(fs.readFileSync("/workspace/probes/parabr-5b.labels.json","utf8"));
const esc=s=>s==null?"null":JSON.stringify(s).replace(/[�--￿]/g,c=>"\\u"+c.charCodeAt(0).toString(16).padStart(4,"0"));
out.forEach((r,i)=>{ console.log((lab[i]||"?").padEnd(18), esc(r.input), "=>", esc(r.output)); });
'

