input.content:
import { readFileSync } from 'node:fs';
const out = JSON.parse(readFileSync('/workspace/probes/parabr-5b.out.json', 'utf8'));
const lab = JSON.parse(readFileSync('/workspace/probes/parabr-5b.labels.json', 'utf8'));
const esc = (s) => {
  if (s == null) return 'null';
  let r = '"';
  for (const ch of s) {
    const c = ch.codePointAt(0);
    if (c === 0x0a) r += '\\n';
    else if (c === 0x09) r += '\\t';
    else if (c === 0x22) r += '\\"';
    else if (c === 0x5c) r += '\\\\';
    else if (c < 0x20 || c === 0x7f || c > 0x7e) r += '\\u' + c.toString(16).padStart(4, '0');
    else r += ch;
  }
  return r + '"';
};
out.forEach((r, i) => {
  console.log((lab[i] || '?').padEnd(18) + esc(r.input) + '  =>  ' + esc(r.output));
});

