// Minimal re-implementation of the paragraph/linebreak pipeline (no regex),
// restricted to plain-text input (no block markers, <4 space indents).
function expandtabs(s, n) {
  let out = '';
  let col = 0;
  for (const ch of s) {
    if (ch === '\t') {
      const add = n - (col % n);
      out += ' '.repeat(add);
      col += add;
    } else if (ch === '\n' || ch === '\r') {
      out += ch;
      col = 0;
    } else {
      out += ch;
      col += 1;
    }
  }
  return out;
}

// Python str.isspace() for BMP chars we care about
const PY_WS = new Set([0x09,0x0a,0x0b,0x0c,0x0d,0x1c,0x1d,0x1e,0x1f,0x20,0x85,0xa0,
  0x1680,0x2000,0x2001,0x2002,0x2003,0x2004,0x2005,0x2006,0x2007,0x2008,0x2009,0x200a,
  0x2028,0x2029,0x202f,0x205f,0x3000]);
const isPyWs = (ch) => PY_WS.has(ch.codePointAt(0));
function pyLstrip(s) { let i = 0; while (i < s.length && isPyWs(s[i])) i++; return s.slice(i); }
function pyStrip(s) {
  let i = 0, j = s.length;
  while (i < j && isPyWs(s[i])) i++;
  while (j > i && isPyWs(s[j - 1])) j--;
  return s.slice(i, j);
}

function normalizeWhitespace(text) {
  // 1. drop STX/ETX
  let s = '';
  for (const ch of text) { const c = ch.charCodeAt(0); if (c !== 2 && c !== 3) s += ch; }
  // 2. CRLF -> LF, CR -> LF
  let t = '';
  for (let i = 0; i < s.length; i++) {
    if (s[i] === '\r') { if (s[i + 1] === '\n') i++; t += '\n'; } else t += s[i];
  }
  // 3. append \n\n
  t += '\n\n';
  // 4. expandtabs(4)
  t = expandtabs(t, 4);
  // 5. drop spaces on space-only lines (except the first line of the doc)
  const lines = t.split('\n');
  for (let i = 1; i < lines.length; i++) {
    const L = lines[i];
    if (L.length > 0) {
      let allSp = true;
      for (const ch of L) if (ch !== ' ') { allSp = false; break; }
      // must be followed by a \n: true for every element except the last
      if (allSp && i < lines.length - 1) lines[i] = '';
    }
  }
  return lines.join('\n');
}

function escText(s) {
  let r = '';
  for (const ch of s) {
    if (ch === '&') r += '&amp;';
    else if (ch === '<') r += '&lt;';
    else if (ch === '>') r += '&gt;';
    else r += ch;
  }
  return r;
}

// inline: only the linebreak pattern "  \n" -> <br />
function renderInline(text) {
  // build [text, br, tail, br, tail...] then apply prettify br rule
  const parts = [];
  let cur = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === ' ' && text[i + 1] === ' ' && text[i + 2] === '\n') {
      parts.push(cur); cur = ''; parts.push(null); i += 3;
    } else { cur += text[i]; i++; }
  }
  parts.push(cur);
  // parts: text, null, tail, null, tail ...
  let out = escText(parts[0]);
  for (let k = 1; k < parts.length; k += 2) {
    let tail = parts[k + 1];
    if (pyStrip(tail) === '') tail = '\n'; else tail = '\n' + tail;
    out += '<br />' + escText(tail).replace('&', '&'); // tail escaping same
  }
  // careful: escText applied to tail above already
  return out;
}

function renderInline2(text) {
  const segs = [];
  let cur = '';
  let i = 0;
  while (i < text.length) {
    if (text[i] === ' ' && text[i + 1] === ' ' && text[i + 2] === '\n') {
      segs.push(cur); cur = ''; i += 3;
    } else { cur += text[i]; i++; }
  }
  segs.push(cur);
  let out = escText(segs[0]);
  for (let k = 1; k < segs.length; k++) {
    let tail = segs[k];
    tail = (pyStrip(tail) === '') ? '\n' : '\n' + tail;
    out += '<br />' + escText(tail);
  }
  return out;
}

export function convert(src) {
  const text = normalizeWhitespace(src);
  const blocks = text.split('\n\n');
  const outParts = [];
  const queue = blocks.slice();
  while (queue.length) {
    const block = queue.shift();
    if (block === '' || block[0] === '\n') {           // EmptyBlockProcessor
      if (block !== '') { const rest = block.slice(1); if (rest) queue.unshift(rest); }
      continue;
    }
    if (pyStrip(block) === '') continue;               // ParagraphProcessor: falsy
    outParts.push('<p>' + renderInline2(pyLstrip(block)) + '</p>');
  }
  return outParts.join('\n');
}

