const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (a) => a[Math.floor(rnd() * a.length)];

const words = ['alpha', 'beta', 'gamma', 'delta', '你好', '世界', 'x', 'word1', '日本', 'ok'];
const leadOpts = ['', ' ', '  ', '   ', '\t'];   // tab -> 4 spaces => code; keep but filter later
const trailOpts = ['', ' ', '  ', '   ', '    ', '\t'];

function randLine() {
  const r = rnd();
  if (r < 0.18) return pick(['', ' ', '  ', '   ', '\t', '    ']);   // blank-ish
  let lead = pick(['', ' ', '  ', '   ']);
  let n = 1 + Math.floor(rnd() * 3);
  let body = [];
  for (let i = 0; i < n; i++) body.push(pick(words));
  let trail = pick(trailOpts);
  return lead + body.join(pick([' ', '  ', '\t'])) + trail;
}

const cases = [];
for (let k = 0; k < 400; k++) {
  const nl = 1 + Math.floor(rnd() * 7);
