    else if (ch === '\n') { out += ch; col = 0; }
    else { out += ch; col++; }
  }
  return out;
}
const kept = cases.filter((s) => {
  const t = expandtabs(s, 4);
  for (const L of t.split('\n')) {
    if (L.startsWith('    ') && L.trim() !== '') return false;
  }
  return true;
}).filter((s) => s.length && !s.startsWith('-'));

