import { writeFileSync } from 'node:fs';
import { convert } from './paraimpl.mjs';

let seed = 987654321;
const rnd = () => { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; };
const pick = (a) => a[Math.floor(rnd() * a.length)];
const C = (n) => String.fromCharCode(n);

const words = ['alpha', 'beta', '你好', '世界', 'x', 'w1', '日本語', 'ok', 'e' + C(0xa0) + 'f', 'z' + C(0x200b)];
const trailOpts = ['', ' ', '  ', '   ', '    ', '     ', '\t', ' \t', '\t ', C(0xa0), C(0x0b)];
const blanks = ['', ' ', '  ', '   ', '\t', '    ', C(0x0b), C(0xa0), C(0x3000), ' ' + C(0x0b)];

function randLine() {
  const r = rnd();
  if (r < 0.22) return pick(blanks);
  const lead = pick(['', ' ', '  ', '   ']);
  const n = 1 + Math.floor(rnd() * 3);
  const body = [];
  for (let i = 0; i < n; i++) body.push(pick(words));
  return lead + body.join(pick([' ', '  ', '\t'])) + pick(trailOpts);
}

function expandtabs(s, n) {
  let out = '', col = 0;
  for (const ch of s) {
    if (ch === '\t') { const a = n - (col % n); out += ' '.repeat(a); col += a; }
    else if (ch === '\n' || ch === '\r') { out += ch; col = 0; }
    else { out += ch; col++; }
  }
  return out;
}

const cases = [];
for (let k = 0; k < 900; k++) {
  const nl = 1 + Math.floor(rnd() * 8);
  const lines = [];
  for (let i = 0; i < nl; i++) lines.push(randLine());
  const sep = pick(['\n', '\n', '\n', '\r\n', '\r']);
  let s = lines.join(sep);
  if (rnd() < 0.3) s += '\n';
  if (rnd() < 0.15) s += '\n\n';
  cases.push(s);
}

const kept = cases.filter((s) => {
  if (!s.length) return false;
  if (s[0] === '-') return false;
  let t = s.split('\r\n').join('\n').split('\r').join('\n');
  t = expandtabs(t + '\n\n', 4);
  const L = t.split('\n');
  // reject anything that could trigger the code-block processor:
  // line 0 being >=4 spaces, or any block-initial 4-space line
  if (L[0].startsWith('    ')) return false;
  for (let i = 0; i < L.length; i++) {
    if (L[i].startsWith('    ')) {
      // block-initial if previous effective line is blank
      let prev = i > 0 ? L[i - 1] : '';
      let prevBlank = prev.trim() === '';
      if (prevBlank) return false;
    }
  }
  return true;
});

const use = kept.slice(0, 260);
writeFileSync('/workspace/probes/parabr-rand2.json', JSON.stringify(use));
writeFileSync('/workspace/probes/parabr-rand2.expect.json', JSON.stringify(use.map(convert)));
console.log('cases:', use.length);

